export function findById(id) { return FACILITIES.find(x => x.id === id); }
export function search(q) {
  const s = String(q||'').toLowerCase();
  if (!s) return FACILITIES.slice();
  return FACILITIES.filter(x => JSON.stringify(x).toLowerCase().includes(s));
}
export function bySpecialty(spec) {
  return FACILITIES.filter(x => (x.specialty||x.category||'').toLowerCase() === String(spec||'').toLowerCase());
}
export function enabledOnly() { return FACILITIES.filter(x => x.enabled !== false); }
export const COUNT = FACILITIES.length;
